<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue'
import {api,action} from '../api'
import Pagination from './Pagination.vue'
const props=defineProps<{workspaces:any[]}>()
const form=ref({tool:'',status:'',workspace_id:'',client:'',actor:'',trace_id:'',start:'',end:''})
const applied=ref<Record<string,string>>({}),items=ref<any[]>([]),stats=ref<any>(null),detail=ref<any>(null),page=ref(1),size=ref(20),total=ref(0),pages=ref(1),busy=ref(false)
const labels:Record<string,string>={running:'执行中',succeeded:'成功',failed:'失败',rejected:'拒绝',cancelled:'取消',interrupted:'中断'}
const phases:Record<string,string>={authorize:'权限检查','tool.execute':'工具执行',audit:'操作审计'}
const autoRefresh=ref(false),clock=ref(Date.now())
let timer:ReturnType<typeof setInterval>,sequence=0,detailSequence=0
onMounted(()=>{timer=setInterval(()=>{clock.value=Date.now();if(autoRefresh.value&&!busy.value)void load().catch(()=>{})},5000)})
onUnmounted(()=>{sequence++;detailSequence++;clearInterval(timer)})
function elapsed(row:any){return row.status==='running'?Math.max(0,clock.value-Date.parse(row.started_at)):row.duration_ms}
async function load(target=page.value){const seq=++sequence;busy.value=true;try{const query=new URLSearchParams(applied.value);query.set('page',String(target));query.set('page_size',String(size.value));const [rows,summary]=await Promise.all([api(`/call-traces?${query}`),api(`/call-traces/statistics?${new URLSearchParams(applied.value)}`)]);if(seq!==sequence)return;items.value=rows.items;page.value=rows.page;pages.value=rows.pages;total.value=rows.total;stats.value=summary;const selected=detail.value?.id,selection=detailSequence;if(selected){try{const fresh=await api(`/call-traces/${selected}`);if(seq===sequence&&selection===detailSequence&&detail.value?.id===selected)detail.value=fresh}catch{}}}finally{if(seq===sequence)busy.value=false}}
async function filter(){const values:Record<string,string>={...form.value};for(const key of ['start','end'])if(values[key])values[key]=new Date(values[key]).toISOString();applied.value=values;detailSequence++;detail.value=null;await action(()=>load(1),'')}
async function inspect(id:string){const seq=++detailSequence;await action(async()=>{const value=await api(`/call-traces/${id}`);if(seq===detailSequence)detail.value=value},'')}
function date(value:string){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'未结束'}
function project(id:string){return props.workspaces.find(w=>w.workspace_id===id)?.name||id||'全局／未指定'}
function ms(value:number){return value>=1000?(value/1000).toFixed(2)+' 秒':Number(value||0).toFixed(1)+' 毫秒'}
void action(()=>load(1),'')
</script>
<template>
<div class="page-title"><div><h1>MCP 调用监控</h1><p>按时间、调用方、工具与项目查看服务执行记录，定位失败和耗时。</p></div><div class="actions"><label class="check"><input type="checkbox" v-model="autoRefresh">每 5 秒刷新</label><button @click="action(()=>load(),'记录已刷新')" :disabled="busy">刷新记录</button></div></div>
<p class="muted">客户端名称来自 MCP 初始化声明；本地免认证调用不能确认真实用户身份。统计仅覆盖本服务，后台任务耗时与请求耗时分别展示。</p>
<form class="trace-filters" @submit.prevent="filter"><label>工具<input v-model="form.tool" placeholder="工具名称（精确匹配）"></label><label>客户端<input v-model="form.client" placeholder="客户端名称（精确匹配）"></label><label>凭据主体<input v-model="form.actor" placeholder="主体 ID"></label><label>状态<select aria-label="调用状态" v-model="form.status"><option value="">全部状态</option><option v-for="(name,key) in labels" :key="key" :value="key">{{name}}</option></select></label><label>项目<select aria-label="调用项目" v-model="form.workspace_id"><option value="">全部项目</option><option v-for="w in workspaces" :key="w.workspace_id" :value="w.workspace_id">{{w.name}}</option></select></label><label>开始时间<input type="datetime-local" v-model="form.start"></label><label>结束时间<input type="datetime-local" v-model="form.end"></label><label>链路 ID<input v-model="form.trace_id" placeholder="精确查找"></label><button class="primary" :disabled="busy">筛选记录</button></form>
<div v-if="stats" class="trace-metrics"><article><small>请求记录</small><strong>{{stats.total}}</strong></article><article><small>成功率（已结束请求）</small><strong>{{stats.ended_count?(stats.success_rate*100).toFixed(1)+'%':'—'}}</strong></article><article><small>失败／拒绝／中断</small><strong>{{stats.failed}}</strong></article><article><small>平均执行耗时</small><strong>{{ms(stats.avg_ms)}}</strong></article><article><small>最长执行耗时</small><strong>{{ms(stats.max_ms)}}</strong></article></div>
<p v-if="stats?.dropped_records" class="error">当前进程有 {{stats.dropped_records}} 次记录写入失败，统计存在缺口。</p>
<details v-if="stats" class="trace-summary"><summary>工具、错误与调用方统计（各前 20 项）</summary><div class="summary-grid"><section><h3>工具调用</h3><table><tbody><tr v-for="row in stats.tools" :key="row.tool"><td>{{row.tool}}</td><td>{{row.count}} 次／{{row.failed}} 次失败</td><td>{{ms(row.avg_ms)}}</td></tr></tbody></table></section><section><h3>错误分布</h3><p v-if="!stats.errors.length">当前筛选范围没有错误。</p><p v-for="row in stats.errors" :key="row.code">{{row.code}} · {{row.count}} 次</p><h3>调用方</h3><p v-for="row in stats.clients" :key="row.client+row.actor">{{row.client}} · {{row.actor}} · {{row.count}} 次</p></section></div></details>
<div class="table-wrap"><table><thead><tr><th>开始时间</th><th>工具／项目</th><th>调用方</th><th>状态</th><th>耗时</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td>{{date(row.started_at)}}<small class="mono">{{row.id}}</small></td><td><strong>{{row.tool}}</strong><small>{{project(row.workspace_id)}}</small></td><td>{{row.client}}<small>{{row.actor}} · {{row.caller?.identity_assurance==='credential'?'凭据认证':'身份未验证'}}</small></td><td><span :class="['trace-state',row.status]">{{labels[row.status]}}</span><small v-if="row.error_code" class="error">{{row.error_code}}</small></td><td>{{ms(elapsed(row))}}{{row.status==='running'?'（进行中）':''}}</td><td><button @click="inspect(row.id)">查看链路</button></td></tr></tbody></table></div>
<p v-if="!items.length&&!busy" class="empty">没有匹配的调用记录。新调用会自动记录；历史日志不会补造链路。</p>
<Pagination :page="page" :page-size="size" :total="total" :pages="pages" label="MCP 调用记录" :busy="busy" @change="action(()=>load($event),'')" @size="size=$event;action(()=>load(1),'')"/>
<section v-if="detail" class="trace-detail"><div class="panel-heading"><h2>调用链路 · {{detail.tool}}</h2><button @click="detailSequence++;detail=null">关闭链路</button></div><p class="mono">{{detail.id}}</p><div class="summary-grid"><p>开始：{{date(detail.started_at)}}<br>结束：{{date(detail.finished_at)}}<br>服务执行：{{ms(elapsed(detail))}}{{detail.status==='running'?'（进行中）':''}}</p><p>客户端：{{detail.client}} {{detail.caller.client_version}}（自报）<br>主体：{{detail.actor}}（{{detail.caller.identity_assurance==='credential'?'凭据认证':'未验证真实身份'}}）<br>来源地址：{{detail.caller.peer||'未提供'}}</p></div><p v-if="detail.error_code" class="error">{{labels[detail.status]}} · {{detail.error_code}} · 可用此链路 ID 定位调用。</p><p v-if="detail.outcome" class="muted">业务结果：{{detail.outcome}}。未命中属于有效查询结果，不等同于执行失败。</p><p class="muted">参数字段：{{detail.argument_keys.join('、')||'无'}}；不保存参数值或响应正文。</p><div v-for="(stage,i) in detail.spans" :key="i" class="trace-stage"><div><strong>{{phases[stage.name]||stage.name}}</strong><span>{{labels[stage.status]}} · {{ms(elapsed(stage))}}</span></div><div class="stage-track"><div :style="{width:Math.min(100,100*stage.duration_ms/Math.max(1,detail.duration_ms))+'%'}" :class="stage.status"></div></div><small>{{date(stage.started_at)}} → {{date(stage.finished_at)}} {{stage.error_code}}</small></div><section v-if="detail.linked_job" class="linked-job"><h3>关联后台任务</h3><p>{{detail.linked_job.id}} · {{labels[detail.linked_job.status]||detail.linked_job.status}} · {{detail.linked_job.phase}}</p><p>开始：{{date(detail.linked_job.started_at)}} · 结束：{{date(detail.linked_job.finished_at)}}</p><p v-if="detail.linked_job.error" class="error">{{detail.linked_job.error}} · 诊断 ID {{detail.linked_job.diagnostics?.trace_id}}</p><ul><li v-for="(stage,i) in detail.linked_job.events||[]" :key="i">{{stage.phase}} · {{date(stage.started_at)}} · 距任务开始 {{stage.elapsed_seconds}} 秒</li></ul><button @click="inspect(detail.id)">刷新关联任务</button></section><p v-if="detail.linked_job_missing" class="muted">关联任务记录已删除，调用记录仍保留。</p></section>
</template>
<style scoped>.trace-filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;background:#fff;padding:24px;border:1px solid #dce3f3;border-radius:14px;margin-bottom:20px}.trace-filters button{align-self:end;width:max-content}.trace-metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;margin-bottom:20px}.trace-metrics article{background:#fff;padding:20px;border-radius:12px;border:1px solid #dce3f3}.trace-metrics strong{display:block;font-size:26px;margin-top:10px}.trace-metrics small{color:#667085}.trace-summary,.trace-detail{background:#fff;padding:24px;border:1px solid #dce3f3;border-radius:14px;margin:20px 0}.summary-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.table-wrap small{display:block;margin-top:6px;font-size:12px;overflow-wrap:anywhere}.trace-state{padding:4px 8px;border-radius:5px;background:#f2f4ff}.failed,.rejected,.interrupted{color:#b42318}.succeeded{color:#067647}.trace-stage{margin:18px 0}.trace-stage>div:first-child{display:flex;justify-content:space-between}.stage-track{height:8px;background:#f2f4ff;border-radius:5px;margin:8px 0;overflow:hidden}.stage-track div{height:100%;background:#6355eb}.stage-track div.failed{background:#dc4545}.linked-job{padding:20px;background:#f5f7ff;border-radius:12px}</style>
